def bundle_zip(
    members: dict[str, str] | None = None,
    *,
    manifest: dict | None = None,
    manifest_path: str = MANIFEST_PATH,
) -> bytes:
    """A bundle archive, built in memory.

    Defaults to a well-formed one so each test states only its own
    deviation — a test that had to spell out eight correct members to
    make one wrong is a test whose point is buried.
    """
    buffer = io.BytesIO()
    with zipfile.ZipFile(buffer, "w") as archive:
        if manifest is not None or manifest_path:
            archive.writestr(manifest_path, json.dumps(manifest or GOOD_MANIFEST))
        archive.writestr("vfh_plus/__init__.py", "from vfh_plus.planner import VFHPlusPlanner\n")
